import{_ as l,a0 as p,w as d,s as o,I as a,x as i,a1 as n,A as t,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const m=JSON.parse('{"title":"自动解锁 Linux 上的加密磁盘 | LCTT x X-CMD","titleTemplate":false,"description":"自动解锁 Linux 上的加密磁盘 | LCTT (202011) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"自动解锁 Linux 上的加密磁盘 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"自动解锁 Linux 上的加密磁盘 | LCTT (202011) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202011/20201116 Unlock encrypted disks on Linux automatically","title":"自动解锁 Linux 上的加密磁盘","tag":"202011","desc":""},"relativePath":"202011/20201116 Unlock encrypted disks on Linux automatically.md","filePath":"[post].md"}'),h={name:"202011/20201116 Unlock encrypted disks on Linux automatically.md"};function g(c,s,u,k,b,f){const e=p("Link");return d(),o("div",null,[s[27]||(s[27]=a("h1",{id:"自动解锁-linux-上的加密磁盘",tabindex:"-1"},[i("自动解锁 Linux 上的加密磁盘 "),a("a",{class:"header-anchor",href:"#自动解锁-linux-上的加密磁盘","aria-label":"Permalink to “自动解锁 Linux 上的加密磁盘”"},"​")],-1)),s[28]||(s[28]=a("blockquote",null,[a("p",null,"通过使用网络绑定磁盘加密（NBDE），无需手动输入密码即可打开加密磁盘。")],-1)),s[29]||(s[29]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202011/23/104735lmx18sxxs18f4xcc.jpg",alt:""})],-1)),a("p",null,[s[1]||(s[1]=i("从安全的角度来看，对敏感数据进行加密以保护其免受窥探和黑客的攻击是很重要的。",-1)),s[2]||(s[2]=a("ruby",null,[i("Linux 统一密钥设置"),a("rt",null,"Linux Unified Key Setup")],-1)),s[3]||(s[3]=i("（",-1)),n(e,{href:"https://en.wikipedia.org/wiki/Linux_Unified_Key_Setup"},{default:t(()=>[...s[0]||(s[0]=[i("LUKS",-1)])]),_:1}),s[4]||(s[4]=i("）是一个很好的工具，也是 Linux 磁盘加密的通用标准。因为它将所有相关的设置信息存储在分区头部中，所以它使数据迁移变得简单。",-1))]),a("p",null,[s[6]||(s[6]=i("要使用 LUKS 配置加密磁盘或分区，你需要使用 ",-1)),n(e,{href:"https://gitlab.com/cryptsetup/cryptsetup"},{default:t(()=>[...s[5]||(s[5]=[i("cryptsetup",-1)])]),_:1}),s[7]||(s[7]=i(" 工具。不幸的是，加密磁盘的一个缺点是，每次系统重启或磁盘重新挂载时，你都必须手动提供密码。",-1))]),s[30]||(s[30]=a("p",null,[i("然而，"),a("ruby",null,[i("网络绑定磁盘加密"),a("rt",null,"Network-Bound Disk Encryption")]),i("（NBDE） 可以在没有任何用户干预的情况下自动安全地解锁加密磁盘。它可以在一些 Linux 发行版中使用，包括从 Red Hat Enterprise Linux 7.4、CentOS 7.4 和 Fedora 24 开始，以及之后的后续版本。")],-1)),s[31]||(s[31]=a("p",null,"NBDE 采用以下技术实现：",-1)),a("ul",null,[a("li",null,[n(e,{href:"https://github.com/latchset/clevis"},{default:t(()=>[...s[8]||(s[8]=[i("Clevis 框架",-1)])]),_:1}),s[9]||(s[9]=i("：一个可插拔的框架工具，可自动解密和解锁 LUKS 卷",-1))]),a("li",null,[n(e,{href:"https://github.com/latchset/tang"},{default:t(()=>[...s[10]||(s[10]=[i("Tang 服务器",-1)])]),_:1}),s[11]||(s[11]=i("：用于将加密密钥绑定到网络状态的服务",-1))])]),s[32]||(s[32]=r(`<p>Tang 向 Clevis 客户端提供加密密钥。据 Tang 的开发人员介绍，这为密钥托管服务提供了一个安全、无状态、匿名的替代方案。</p><p>由于 NBDE 使用客户端-服务器架构，你必须同时配置客户端和服务器。你可以在你的本地网络上使用一个虚拟机作为 Tang 服务器。</p><h3 id="服务器安装" tabindex="-1">服务器安装 <a class="header-anchor" href="#服务器安装" aria-label="Permalink to “服务器安装”">​</a></h3><p>用 sudo 安装 Tang：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo yum install tang -y</span></span></code></pre></div><p>启用 Tang 服务器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl enable tangd.socket --now</span></span></code></pre></div><p>Tang 服务器工作在 80 端口，需加入到 firewalld 防火墙。添加相应的 firewalld 规则：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo  firewall-cmd --add-port=tcp/80 --perm</span></span>
<span class="line"><span>sudo firewall-cmd --reload</span></span></code></pre></div><p>现在安装好了服务器。</p><h3 id="客户端安装" tabindex="-1">客户端安装 <a class="header-anchor" href="#客户端安装" aria-label="Permalink to “客户端安装”">​</a></h3><p>在本例中，假设你已经添加了一个名为 <code>/dev/vdc</code> 的新的 1GB 磁盘到你的系统中。</p><p>使用 <code>fdisk</code> 或 <code>parted</code> 创建主分区：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo fdisk /dev/vdc</span></span></code></pre></div><p>完成以下步骤来安装客户端：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Welcome to fdisk (util-linux 2.23.2).</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Changes will remain in memory only, until you decide to write them.</span></span>
<span class="line"><span>Be careful before using the write command.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Device does not contain a recognized partition table</span></span>
<span class="line"><span>Building a new DOS disklabel with disk identifier 0x4a6812d4.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Command (m for help):</span></span></code></pre></div><p>输入 <code>n</code> 来创建新的分区：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Partition type:</span></span>
<span class="line"><span>   p   primary (0 primary, 0 extended, 4 free)</span></span>
<span class="line"><span>   e   extended  </span></span>
<span class="line"><span>Select (default p):</span></span></code></pre></div><p>按下<strong>回车</strong>键选择主分区：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Using default response p</span></span>
<span class="line"><span>Partition number (1-4, default 1):</span></span></code></pre></div><p>按下回车键选择默认分区号：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>First sector (2048-2097151, default 2048):</span></span>
<span class="line"><span>Using default value 2048</span></span>
<span class="line"><span>Last sector, +sectors or +size{K,M,G} (2048-2097151, default 2097151):</span></span></code></pre></div><p>按回车键选择最后一个扇区：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Using default value 2097151</span></span>
<span class="line"><span>Partition 1 of type Linux and of size 1023 MiB is set</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Command (m for help): wq</span></span></code></pre></div><p>输入 <code>wq</code> 保存更改并退出 <code>fdisk</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>The partition table has been altered!</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Calling ioctl() to re-read partition table.</span></span>
<span class="line"><span>Syncing disks.</span></span></code></pre></div><p>运行 <code>partprobe</code> 通知系统分区表的变化：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo partprobe</span></span></code></pre></div><p>使用 <code>sudo</code> 安装 cryptsetup 软件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo yum install cryptsetup -y</span></span></code></pre></div><p>使用 <code>cryptsetup luksFormat</code> 命令对磁盘进行加密。当提示时，你需要输入大写的 <code>YES</code>，并输入密码来加密磁盘：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo cryptsetup luksFormat /dev/vdc1</span></span>
<span class="line"><span>WARNING!</span></span>
<span class="line"><span>========</span></span>
<span class="line"><span>This will overwrite data on /dev/vdc1 irrevocably.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Are you sure? (Type uppercase yes):</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Enter passphrase for /dev/vdc1:</span></span>
<span class="line"><span>Verify passphrase:</span></span></code></pre></div><p>使用 <code>cryptsetup luksOpen</code> 命令将加密的分区映射到一个逻辑设备上。例如，使用 <code>encryptedvdc1</code> 作为名称。你还需要再次输入密码：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo cryptsetup luksOpen /dev/vdc1 encryptedvdc1</span></span>
<span class="line"><span>Enter passphrase for /dev/vdc1:</span></span></code></pre></div><p>加密分区现在在 <code>/dev/mapper/encryptedvdc1</code> 中可用。</p><p>在加密的分区上创建一个 XFS 文件系统：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo mkfs.xfs /dev/mapper/encryptedvdc1</span></span></code></pre></div><p>创建一个挂载加密分区的目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo mkdir /encrypted</span></span></code></pre></div><p>使用 <code>cryptsetup luksClose</code> 命令锁定分区：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cryptsetup luksClose encryptedvdc1</span></span></code></pre></div><p>使用 <code>sudo</code> 安装 Clevis 软件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo yum install clevis clevis-luks clevis-dracut -y</span></span></code></pre></div><p>修改 <code>/etc/crypttab</code>，在启动时打开加密卷：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo vim /etc/crypttab</span></span></code></pre></div><p>增加以下一行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>encryptedvdc1       /dev/vdc1  none   _netdev</span></span></code></pre></div><p>修改 <code>/etc/fstab</code>，在重启时或启动时自动挂载加密卷：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo vim /etc/fstab</span></span></code></pre></div><p>增加以下一行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/dev/mapper/encryptedvdc1   /encrypted       xfs    _netdev        1 2</span></span></code></pre></div><p>在这个例子中，假设 Tang 服务器的 IP 地址是 <code>192.168.1.20</code>。如果你喜欢，也可以使用主机名或域名。</p><p>运行以下 <code>clevis</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo clevis bind luks -d /dev/vdc1 tang &#39;{&quot;url&quot;:&quot;http://192.168.1.20&quot;}&#39;</span></span>
<span class="line"><span>The advertisement contains the following signing keys:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>rwA2BAITfYLuyNiIeYUMBzkhk7M</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Do you wish to trust these keys? [ynYN] Y</span></span>
<span class="line"><span>Enter existing LUKS password:</span></span></code></pre></div><p>输入 <code>Y</code> 接受 Tang 服务器的密钥，并提供现有的 LUKS 密码进行初始设置。</p><p>通过 <code>systemctl</code> 启用 <code>clevis-luks-askpass.path</code>，以防止非根分区被提示输入密码。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl enable clevis-luks-askpass.path</span></span></code></pre></div><p>客户端已经安装完毕。现在，每当你重启服务器时，加密后的磁盘应该会自动解密，并通过 Tang 服务器取回密钥进行挂载。</p><p>如果 Tang 服务器因为任何原因不可用，你需要手动提供密码，才能解密和挂载分区。</p><hr>`,60)),a("p",null,[s[13]||(s[13]=i("via: ",-1)),n(e,{href:"https://opensource.com/article/20/11/nbde-linux"},{default:t(()=>[...s[12]||(s[12]=[i("https://opensource.com/article/20/11/nbde-linux",-1)])]),_:1})]),a("p",null,[s[18]||(s[18]=i("作者：",-1)),n(e,{href:"https://opensource.com/users/rcurtiswarfield"},{default:t(()=>[...s[14]||(s[14]=[i("Curt Warfield",-1)])]),_:1}),s[19]||(s[19]=i(" 选题：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[15]||(s[15]=[i("lujun9972",-1)])]),_:1}),s[20]||(s[20]=i(" 译者：",-1)),n(e,{href:"https://github.com/geekpi"},{default:t(()=>[...s[16]||(s[16]=[i("geekpi",-1)])]),_:1}),s[21]||(s[21]=i(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[17]||(s[17]=[i("wxy",-1)])]),_:1})]),a("p",null,[s[24]||(s[24]=i("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[22]||(s[22]=[i("LCTT",-1)])]),_:1}),s[25]||(s[25]=i(" 原创编译，",-1)),n(e,{href:"https://linux.cn/"},{default:t(()=>[...s[23]||(s[23]=[i("Linux中国",-1)])]),_:1}),s[26]||(s[26]=i(" 荣誉推出",-1))])])}const C=l(h,[["render",g]]);export{m as __pageData,C as default};
